solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

struct Export { std::uint32_t rva; std::string forwarder; };

static std::uint32_t u32(const std::vector<std::uint8_t>& b, std::uint32_t at)
{
    return b[at] | (b[at + 1] << 8) | (b[at + 2] << 16) | (static_cast<std::uint32_t>(b[at + 3]) << 24);
}
static std::uint16_t u16(const std::vector<std::uint8_t>& b, std::uint32_t at) { return static_cast<std::uint16_t>(b[at] | (b[at + 1] << 8)); }
static std::string text(const std::vector<std::uint8_t>& b, std::uint32_t at)
{
    std::string s;
    while (at < b.size() && b[at] != 0) s += static_cast<char>(b[at++]);
    return s;
}

std::string dllName(const std::vector<std::uint8_t>& image, std::uint32_t dirRva) { return text(image, u32(image, dirRva + 12)); }

static std::optional<Export> byIndex(const std::vector<std::uint8_t>& image, std::uint32_t dirRva, std::uint32_t dirSize, std::uint32_t index)
{
    if (index >= u32(image, dirRva + 20)) return std::nullopt;
    const std::uint32_t rva{ u32(image, u32(image, dirRva + 28) + 4 * index) };
    if (rva == 0) return std::nullopt;
    Export e{ rva, "" };
    if (rva >= dirRva && rva < dirRva + dirSize) e.forwarder = text(image, rva);
    return e;
}

std::optional<Export> findByName(const std::vector<std::uint8_t>& image, std::uint32_t dirRva, std::uint32_t dirSize, std::string_view name)
{
    const std::uint32_t names{ u32(image, dirRva + 32) }, ordinals{ u32(image, dirRva + 36) };
    std::uint32_t lo{ 0 }, hi{ u32(image, dirRva + 24) };
    while (lo < hi)
    {
        const std::uint32_t mid{ lo + (hi - lo) / 2 };
        const std::string candidate{ text(image, u32(image, names + 4 * mid)) };
        const int order{ std::string_view{ candidate }.compare(name) };
        if (order == 0) return byIndex(image, dirRva, dirSize, u16(image, ordinals + 2 * mid));
        if (order < 0) lo = mid + 1; else hi = mid;
    }
    return std::nullopt;
}

std::optional<Export> findByOrdinal(const std::vector<std::uint8_t>& image, std::uint32_t dirRva, std::uint32_t dirSize, std::uint32_t ordinal)
{
    const std::uint32_t base{ u32(image, dirRva + 16) };
    if (ordinal < base) return std::nullopt;
    return byIndex(image, dirRva, dirSize, ordinal - base);
}

