#include <cstring>
using Bytes = std::vector<std::uint8_t>;
static void put(Bytes& b, std::size_t at, std::uint64_t v, int n) { for (int i{ 0 }; i < n; ++i) b[at + i] = static_cast<std::uint8_t>(v >> (8 * i)); }
static void str(Bytes& b, std::size_t at, const char* s) { std::memcpy(&b[at], s, std::strlen(s) + 1); }
// game.dll: export directory at 0x100 (size 0x300). Functions: [0x1010, 0x1020, 0x380 (a forwarder), 0x1040, 0]
static Bytes image()
{
    Bytes b(0x2000, 0);
    put(b, 0x100 + 12, 0x200, 4); put(b, 0x100 + 16, 1, 4); put(b, 0x100 + 20, 5, 4); put(b, 0x100 + 24, 3, 4);
    put(b, 0x100 + 28, 0x300, 4); put(b, 0x100 + 32, 0x340, 4); put(b, 0x100 + 36, 0x360, 4);
    str(b, 0x200, "game.dll");
    str(b, 0x250, "Attack"); str(b, 0x260, "Heal"); str(b, 0x270, "Zero");
    put(b, 0x300, 0x1010, 4); put(b, 0x304, 0x1020, 4); put(b, 0x308, 0x380, 4); put(b, 0x30C, 0x1040, 4); put(b, 0x310, 0, 4);
    put(b, 0x340, 0x250, 4); put(b, 0x344, 0x260, 4); put(b, 0x348, 0x270, 4);
    put(b, 0x360, 1, 2); put(b, 0x362, 0, 2); put(b, 0x364, 2, 2);
    str(b, 0x380, "NTDLL.RtlZeroMemory");
    return b;
}

TEST("the DLL's own name") { CHECK_EQ(dllName(image(), 0x100), std::string("game.dll")); }
TEST("by name") {
    const Bytes b{ image() };
    CHECK_EQ(findByName(b, 0x100, 0x300, "Attack").value_or(Export{ 0, "" }).rva, 0x1020u);
    CHECK_EQ(findByName(b, 0x100, 0x300, "Heal").value_or(Export{ 0, "" }).rva, 0x1010u);
    CHECK(!findByName(b, 0x100, 0x300, "Fly").has_value());
    CHECK(!findByName(b, 0x100, 0x300, "attack").has_value());
    CHECK(!findByName(b, 0x100, 0x300, "").has_value());
}
TEST("forwarders") {
    const Bytes b{ image() };
    const auto zero{ findByName(b, 0x100, 0x300, "Zero") };
    CHECK(zero.has_value());
    if (zero) { CHECK_EQ(zero->forwarder, std::string("NTDLL.RtlZeroMemory")); }
    const auto heal{ findByName(b, 0x100, 0x300, "Heal") };
    if (heal) CHECK_EQ(heal->forwarder, std::string(""));
}
TEST("by ordinal") {
    const Bytes b{ image() };
    CHECK_EQ(findByOrdinal(b, 0x100, 0x300, 1).value_or(Export{ 0, "" }).rva, 0x1010u);
    CHECK_EQ(findByOrdinal(b, 0x100, 0x300, 4).value_or(Export{ 0, "" }).rva, 0x1040u);
    CHECK(!findByOrdinal(b, 0x100, 0x300, 5).has_value());
    CHECK(!findByOrdinal(b, 0x100, 0x300, 6).has_value());
    CHECK(!findByOrdinal(b, 0x100, 0x300, 0).has_value());
}

